// FilterSymbols filters Symbols by optional category and case-insensitive search query.
func FilterSymbols(category, query string) []SymbolItem {
	q := strings.ToLower(strings.TrimSpace(query))
	cat := strings.TrimSpace(category)

	out := make([]SymbolItem, 0, len(Symbols))
	for _, s := range Symbols {
		if cat != "" && q == "" && s.Category != cat {
			continue
		}
		if q != "" {
			if !strings.Contains(strings.ToLower(s.Name), q) &&
				!strings.Contains(strings.ToLower(s.Latex), q) &&
				!strings.Contains(strings.ToLower(s.Keywords), q) &&
				!strings.Contains(strings.ToLower(s.Label), q) {
				continue
			}
		}
		out = append(out, s)
	}
	return out
}
